-- India milestones (Stage 4 deep-dive/tracker migration)
-- 6 total: 4 deep-dive-only + 2 tracker-matched (in-threshold, in-30day),
-- both exact date/event matches with the tracker's own DATA entries -- tracker phrasing wins.

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'in-gst-council-2019', id, '2019-12-01', 0, NULL FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-gst-council-2019', 'en', 'GST Council approves phased B2B e-invoicing', 'The policy decision that sets everything else in motion, followed by a voluntary adoption window from January 2020.', '[]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'in-500cr-2020', id, '2020-10-01', 0, NULL FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-500cr-2020', 'en', 'Mandatory e-invoicing begins — turnover ≥ ₹500 crore', 'The largest taxpayers become the first cohort required to report invoices to an Invoice Registration Portal (IRP) and obtain a valid IRN.', '[]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'in-threshold-reductions', id, '2021-06-01', 0, NULL FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-threshold-reductions', 'en', 'Threshold steps down through successive notifications', 'The turnover bar drops in stages across 2021–2023, bringing progressively smaller businesses into scope with each reduction.', '[]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'in-2fa-2023', id, '2023-07-15', 0, NULL FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-2fa-2023', 'en', 'Two-factor authentication mandatory for large taxpayers', '2FA becomes mandatory on the GST portal for taxpayers with AATO above ₹100 crore, tightening access security ahead of further threshold reductions.', '[]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'in-threshold', id, '2023-08-01', 1, 'https://einvoice1.gst.gov.in' FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-threshold', 'en', 'GST e-invoicing mandatory above ₹5 crore turnover (in force since Aug 2023)', 'Any GST-registered business with aggregate annual turnover (AATO) exceeding ₹5 crore in any financial year since 2017–18 must generate e-invoices with a valid IRN for B2B and export transactions.', '["Confirm aggregate turnover across all GSTINs under your PAN — it only needs to exceed ₹5 crore once", "Register with an Invoice Registration Portal (IRP) — NIC''s einvoice1.gst.gov.in or an authorised private IRP", "Watch for a possible threshold reduction to ₹2 crore, discussed but not yet notified"]');
INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url) SELECT 'in-30day', id, '2025-04-01', 0, 'https://einvoice1.gst.gov.in' FROM countries WHERE name_en = 'India';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('in-30day', 'en', '30-day IRN reporting window (AATO ≥ ₹10 crore)', 'Invoices, credit notes and debit notes older than 30 days can no longer be reported to the IRP for IRN generation — they will be rejected outright for taxpayers with AATO of ₹10 crore or more.', '["Build the 30-day reporting window into your AP/AR workflow", "Enable multi-factor authentication on the GST portal — mandatory since April 2025"]');
